"""API request handling."""

from typing import Any


def _validate_request(data: Any, request_id: Any) -> None:
    """Validate the values required to process and audit a request.

    Request payloads are expected to be JSON objects, and request IDs must be
    non-empty strings so they can be used reliably by the audit log.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not isinstance(request_id, str):
        raise TypeError("request_id must be a string")

    if not request_id.strip():
        raise ValueError("request_id must not be empty")


def handle_request(data: Any, request_id: Any) -> Any:
    """Validate, audit, and process an incoming API request."""
    _validate_request(data, request_id)
    audit_log(request_id, data)
    return process(data)

